DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `OrderId` int NOT NULL AUTO_INCREMENT,
  `OrderDate` datetime(6) NOT NULL,
  `DeliveryDate` datetime(6) NOT NULL,
  `CustomerId` int NOT NULL,
  `TotalAmount` decimal(65,30) NOT NULL,
  `IsPaid` tinyint(1) NOT NULL,
  `PaymentDate` datetime(6) DEFAULT NULL,
  `Notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `OrderSource` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'Regular',
  `IsShipped` tinyint(1) NOT NULL DEFAULT '0',
  `ShippedDate` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`OrderId`),
  KEY `IX_Orders_CustomerId` (`CustomerId`),
  CONSTRAINT `FK_Orders_Customers_CustomerId` FOREIGN KEY (`CustomerId`) REFERENCES `customers` (`CustomerId`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
